solution.solution.c:
#include <math.h>

enum shape_kind { CIRCLE, RECTANGLE, TRIANGLE };

typedef struct {
    enum shape_kind kind;
    union {
        struct { double radius; } circle;
        struct { double width, height; } rectangle;
        struct { double a, b, c; } triangle;
    };
} Shape;

static const double PI = 3.14159265358979323846;

const char *kind_name(enum shape_kind kind)
{
    switch (kind) {
    case CIRCLE: return "circle";
    case RECTANGLE: return "rectangle";
    case TRIANGLE: return "triangle";
    }
    return "unknown";
}

double area(const Shape *s)
{
    switch (s->kind) {
    case CIRCLE:
        return PI * s->circle.radius * s->circle.radius;
    case RECTANGLE:
        return s->rectangle.width * s->rectangle.height;
    case TRIANGLE: {
        double a = s->triangle.a, b = s->triangle.b, c = s->triangle.c;
        double p = (a + b + c) / 2;
        return sqrt(p * (p - a) * (p - b) * (p - c));
    }
    }
    return 0;
}

double perimeter(const Shape *s)
{
    switch (s->kind) {
    case CIRCLE: return 2 * PI * s->circle.radius;
    case RECTANGLE: return 2 * (s->rectangle.width + s->rectangle.height);
    case TRIANGLE: return s->triangle.a + s->triangle.b + s->triangle.c;
    }
    return 0;
}

Shape make_square(double side)
{
    Shape s = {.kind = RECTANGLE, .rectangle = {side, side}};
    return s;
}

unitTests:
TEST("names") { CHECK_EQ(kind_name(CIRCLE), "circle"); CHECK_EQ(kind_name(RECTANGLE), "rectangle"); CHECK_EQ(kind_name(TRIANGLE), "triangle"); }
TEST("circles") { Shape c = {.kind = CIRCLE, .circle = {2}}; CHECK_NEAR(area(&c), 12.566370614359172, 1e-9); CHECK_NEAR(perimeter(&c), 12.566370614359172, 1e-9); }
TEST("rectangles") { Shape r = {.kind = RECTANGLE, .rectangle = {3, 4}}; CHECK_NEAR(area(&r), 12.0, 1e-9); CHECK_NEAR(perimeter(&r), 14.0, 1e-9); }
TEST("triangles") { Shape t = {.kind = TRIANGLE, .triangle = {3, 4, 5}}; CHECK_NEAR(area(&t), 6.0, 1e-9); CHECK_NEAR(perimeter(&t), 12.0, 1e-9); Shape e = {.kind = TRIANGLE, .triangle = {2, 2, 2}}; CHECK_NEAR(area(&e), 1.7320508075688772, 1e-9); }
TEST("making a square") { Shape s = make_square(5); CHECK_EQ(kind_name(s.kind), "rectangle"); CHECK_NEAR(s.rectangle.width, 5.0, 1e-9); CHECK_NEAR(s.rectangle.height, 5.0, 1e-9); CHECK_NEAR(area(&s), 25.0, 1e-9); }

